def priority(item: float, bins: np.ndarray) -> np.ndarray:
    priorities = np.full_like(bins, -np.inf, dtype=float)
    greater_mask = bins > item
    equal_mask = bins == item
    less_mask = bins < item

    if np.any(equal_mask):
        priorities[equal_mask] = np.inf
    if np.any(greater_mask):
        priorities[greater_mask] = -bins[greater_mask]
    if np.any(less_mask):
        priorities[less_mask] = bins[less_mask]

    return priorities
